#!/usr/bin/env python3
"""Fail-closed direct-disk cache drain. CLI configuration is generated by Nix.

Receipts are evidence, not authority: release rechecks mount identity, parity
state, both hashes and metadata, and takes a kernel read lease on each source.
All opens walk from pinned directory fds with O_NOFOLLOW. No union destination.
"""

import argparse
import contextlib
import ctypes
import errno
import fcntl
import fnmatch
import hashlib
import json
import os
from pathlib import PurePosixPath
import re
import signal
import stat
import subprocess
import sys
import time
import uuid
from typing import Iterator


class Unsafe(RuntimeError):
    pass


DIR = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
READ = os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NOATIME | os.O_NONBLOCK


def require(ok: bool, reason: str) -> None:
    if not ok:
        raise Unsafe(reason)


def parts(path: str) -> list[str]:
    result = path.split("/")
    require(
        bool(path) and all(p not in ("", ".", "..") for p in result),
        "unsafe relative path",
    )
    return result


def mount_id(fd: int) -> str:
    with open(f"/proc/self/fdinfo/{fd}") as stream:
        return next(line.split()[1] for line in stream if line.startswith("mnt_id:"))


class Root:
    def __init__(self, path: str):
        require(path.startswith("/") and path != "/", "root must be absolute, not /")
        self.path = path
        self.fd = os.open("/", DIR)
        try:
            for component in parts(path[1:]):
                child = os.open(component, DIR, dir_fd=self.fd)
                os.close(self.fd)
                self.fd = child
        except BaseException:
            os.close(self.fd)
            raise
        self.mount = mount_id(self.fd)
        self.device = os.fstat(self.fd).st_dev

    def close(self) -> None:
        os.close(self.fd)

    def attached(self) -> None:
        other = Root(self.path)
        try:
            require(
                other.mount == self.mount and os.fstat(other.fd) == os.fstat(self.fd),
                "root detached or changed",
            )
        finally:
            other.close()

    @contextlib.contextmanager
    def parent(self, path: str, create: bool = False) -> Iterator[tuple[int, str]]:
        components = parts(path)
        fd = os.dup(self.fd)
        try:
            for component in components[:-1]:
                if create:
                    try:
                        os.mkdir(component, 0o750, dir_fd=fd)
                        os.fsync(fd)
                    except FileExistsError:
                        pass
                child = os.open(component, DIR, dir_fd=fd)
                os.close(fd)
                fd = child
                require(mount_id(fd) == self.mount, "nested mount refused")
            yield fd, components[-1]
        finally:
            os.close(fd)

    @contextlib.contextmanager
    def file(self, path: str) -> Iterator[int]:
        with self.parent(path) as (parent, name):
            fd = os.open(name, READ, dir_fd=parent)
        try:
            require(mount_id(fd) == self.mount, "nested file mount refused")
            regular(fd)
            yield fd
        finally:
            os.close(fd)


def regular(fd: int) -> None:
    info = os.fstat(fd)
    require(
        stat.S_ISREG(info.st_mode) and info.st_nlink == 1,
        "only singly-linked regular files are supported",
    )


def snapshot(fd: int) -> dict:
    info = os.fstat(fd)
    return {
        key: getattr(info, "st_" + key)
        for key in (
            "dev",
            "ino",
            "size",
            "mode",
            "uid",
            "gid",
            "mtime_ns",
            "ctime_ns",
            "nlink",
        )
    }


def remove_xattr_if_present(fd: int, key: str) -> None:
    # XFS lists both system.posix_acl_* and trusted.SGI_ACL_* aliases. Removing
    # one removes the other too, so a saved enumeration can contain absent keys.
    try:
        os.removexattr(fd, key)
    except OSError as error:
        if error.errno != errno.ENODATA:
            raise


def metadata(fd: int) -> dict:
    info = os.fstat(fd)
    return {
        "mode": stat.S_IMODE(info.st_mode),
        "uid": info.st_uid,
        "gid": info.st_gid,
        "mtime_ns": info.st_mtime_ns,
        "xattrs": {
            name: os.getxattr(fd, name).hex() for name in sorted(os.listxattr(fd))
        },
    }


def digest(fd: int) -> str:
    before = snapshot(fd)
    os.lseek(fd, 0, os.SEEK_SET)
    result = hashlib.sha256()
    while chunk := os.read(fd, 1024 * 1024):
        result.update(chunk)
    require(snapshot(fd) == before, "file changed while hashing")
    return result.hexdigest()


def digest_path(root: Root, path: str) -> str:
    with root.file(path) as fd:
        return digest(fd)


@contextlib.contextmanager
def lease(fd: int) -> Iterator[None]:
    # F_SETLEASE fails for an already-open writer. A later writer triggers SIGIO
    # and blocks in the kernel; abort rather than waiting for the lease timeout.
    def interrupted(_signum: int, _frame: object) -> None:
        raise Unsafe("file lease broken by a writer; source retained")

    previous = signal.signal(signal.SIGIO, interrupted)
    acquired = False
    try:
        fcntl.fcntl(fd, fcntl.F_SETLEASE, fcntl.F_RDLCK)
        acquired = True
        yield
        require(fcntl.fcntl(fd, fcntl.F_GETLEASE) == fcntl.F_RDLCK, "lease lost")
    finally:
        if acquired:
            fcntl.fcntl(fd, fcntl.F_SETLEASE, fcntl.F_UNLCK)
        signal.signal(signal.SIGIO, previous)


def rename_new(src_fd: int, src: str, dst_fd: int, dst: str) -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    result = libc.renameat2(src_fd, os.fsencode(src), dst_fd, os.fsencode(dst), 1)
    if result:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error), dst)


def distinct(source: Root, target: Root) -> None:
    a, b = PurePosixPath(source.path), PurePosixPath(target.path)
    require(
        a != b and a not in b.parents and b not in a.parents,
        "source and destination overlap",
    )
    require(
        (os.fstat(source.fd).st_dev, os.fstat(source.fd).st_ino)
        != (os.fstat(target.fd).st_dev, os.fstat(target.fd).st_ino),
        "same backing root",
    )


def prepare_directories(source: Root, target: Root, path: str) -> None:
    components = parts(path)
    for length in range(1, len(components)):
        prefix = "/".join(components[:length])
        try:
            with target.parent(prefix + "/unused"):
                pass
            # Preserve genuinely pre-existing directories, including their ACLs.
            continue
        except FileNotFoundError:
            pass
        with source.parent(prefix + "/unused") as (src, _):
            info = os.fstat(src)
            meta = metadata(src)
            with target.parent(prefix) as (parent, name):
                # A private container keeps the entry inaccessible even after
                # setting its final owner/mode/ACL. Never expose an incomplete
                # final name: a restart must not mistake it for an existing dir.
                temporary = ".cache-mover-dir-" + uuid.uuid4().hex
                os.mkdir(temporary, 0o700, dir_fd=parent)
                stage = os.open(temporary, DIR, dir_fd=parent)
                try:
                    os.fchmod(stage, 0o700)
                    os.mkdir("entry", 0o700, dir_fd=stage)
                    fd = os.open("entry", DIR, dir_fd=stage)
                    try:
                        os.fchown(fd, meta["uid"], meta["gid"])
                        os.fchmod(fd, meta["mode"])
                        # mkdir inherits both default and access ACLs. Preserve
                        # the source's exact xattr set, not the target parent's.
                        for key in os.listxattr(fd):
                            if key not in meta["xattrs"]:
                                remove_xattr_if_present(fd, key)
                        for key, value in meta["xattrs"].items():
                            os.setxattr(fd, key, bytes.fromhex(value))
                        os.utime(fd, ns=(info.st_atime_ns, info.st_mtime_ns))
                        require(
                            metadata(fd) == meta,
                            "directory metadata verification failed",
                        )
                        require(
                            metadata(src) == meta, "source directory metadata changed"
                        )
                        os.fsync(fd)
                        os.fsync(stage)
                        source.attached()
                        target.attached()
                        try:
                            rename_new(stage, "entry", parent, name)
                        except FileExistsError:
                            # A concurrent existing directory is not ours to
                            # rewrite. Reject symlinks or nested mounts here.
                            with target.parent(prefix + "/unused"):
                                pass
                            continue
                        os.fsync(parent)
                        os.fsync(stage)
                    finally:
                        os.close(fd)
                    os.rmdir(temporary, dir_fd=parent)
                    os.fsync(parent)
                finally:
                    os.close(stage)
                    # Failed/interrupted initialization stays private for
                    # inspection. A retry creates a fresh initialized entry.


def copy_file(source: Root, target: Root, path: str) -> dict:
    distinct(source, target)
    with source.file(path) as src, lease(src):
        before = snapshot(src)
        meta = metadata(src)
        atime = os.fstat(src).st_atime_ns
        sha = digest(src)
        prepare_directories(source, target, path)
        with target.parent(path) as (parent, name):
            try:
                existing = os.open(name, READ, dir_fd=parent)
            except FileNotFoundError:
                existing = None
            if existing is not None:
                try:
                    regular(existing)
                    require(
                        mount_id(existing) == target.mount, "nested destination mount"
                    )
                    with lease(existing):
                        require(
                            os.fstat(existing).st_atime_ns == atime,
                            "destination access timestamp differs",
                        )
                        require(
                            metadata(existing) == meta and digest(existing) == sha,
                            "destination conflict",
                        )
                        os.fsync(existing)
                finally:
                    os.close(existing)
            else:
                temporary = ".cache-mover-" + uuid.uuid4().hex
                out = os.open(
                    temporary,
                    os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                    0o600,
                    dir_fd=parent,
                )
                try:
                    os.lseek(src, 0, os.SEEK_SET)
                    while chunk := os.read(src, 1024 * 1024):
                        view = memoryview(chunk)
                        while view:
                            written = os.write(out, view)
                            require(written > 0, "short write")
                            view = view[written:]
                    os.fchown(out, meta["uid"], meta["gid"])
                    os.fchmod(out, meta["mode"])
                    for key in os.listxattr(out):
                        if key not in meta["xattrs"]:
                            remove_xattr_if_present(out, key)
                    for key, value in meta["xattrs"].items():
                        os.setxattr(out, key, bytes.fromhex(value))
                    os.utime(out, ns=(atime, meta["mtime_ns"]))
                    os.fsync(out)
                    require(
                        digest(out) == sha and metadata(out) == meta,
                        "copy verification failed",
                    )
                    os.utime(out, ns=(atime, meta["mtime_ns"]))
                    os.fsync(out)
                    require(snapshot(src) == before, "source changed during copy")
                    source.attached()
                    target.attached()
                    rename_new(parent, temporary, parent, name)
                    os.fsync(parent)
                finally:
                    os.close(out)
                    # Never remove an interrupted temporary file automatically:
                    # it may be the only copy after an unrelated operator action.
            require(snapshot(src) == before and metadata(src) == meta, "source changed")
        with target.file(path) as dest:
            return {
                "path": path,
                "source": before,
                "metadata": meta,
                "sha256": sha,
                "destination": snapshot(dest),
                "state": "copied",
            }


def diff_counts(status: int, output: str) -> tuple[int, int]:
    require(status in (0, 2), f"SnapRAID diff failed ({status})")
    counts = []
    for label in ("removed", "updated"):
        values = re.findall(r"^\s*(\d+)\s+" + label + r"\s*$", output, re.MULTILINE)
        require(len(values) == 1, f"missing/ambiguous diff count: {label}")
        counts.append(int(values[0]))
    return counts[0], counts[1]


def protectable(path: str, excludes: list[str]) -> bool:
    components = parts(path)
    if any(p.startswith(".") or p.startswith("snapraid.") for p in components):
        return False
    for pattern in excludes:
        # Deliberately over-exclude when SnapRAID's pattern semantics differ.
        pattern = pattern.strip("/")
        if fnmatch.fnmatchcase(path, pattern) or any(
            fnmatch.fnmatchcase(p, pattern) for p in components
        ):
            return False
        if path.startswith(pattern + "/"):
            return False
    return True


def unescape_mount(text: str) -> str:
    return re.sub(r"\\([0-7]{3})", lambda match: chr(int(match[1], 8)), text)


def admit(root: Root, expected: dict) -> None:
    root.attached()
    with open("/proc/self/mountinfo") as stream:
        entries = [line.split() for line in stream]
    entries = [
        entry
        for entry in entries
        if entry[0] == root.mount and unescape_mount(entry[4]) == root.path
    ]
    require(len(entries) == 1, f"not an exact mounted root: {root.path}")
    entry = entries[0]
    separator = entry.index("-")
    require(entry[separator + 1] == expected["fsType"], "filesystem type mismatch")
    require(
        unescape_mount(entry[3]) == expected.get("fsRoot", "/"),
        "filesystem root mismatch",
    )
    require("rw" in entry[5].split(","), "read-only backing disk")
    dev = os.stat(expected["device"])
    require(stat.S_ISBLK(dev.st_mode), "expected device is not a block device")
    major, minor = (int(value) for value in entry[2].split(":"))
    # btrfs uses an anonymous superblock st_dev. Compare the mounted source to
    # the configured UUID device instead; by-id comparison remains mandatory for XFS.
    actual_dev = os.stat(unescape_mount(entry[separator + 2]))
    if expected["fsType"] != "btrfs":
        require(
            actual_dev.st_rdev == dev.st_rdev,
            "mounted device differs from configured identity",
        )
    else:
        require(bool(expected.get("uuid")), "btrfs cache requires UUID identity")
        mounted_uuid = subprocess.check_output(
            [
                "blkid",
                "-p",
                "-s",
                "UUID",
                "-o",
                "value",
                unescape_mount(entry[separator + 2]),
            ],
            text=True,
        ).strip()
        require(mounted_uuid == expected["uuid"], "btrfs mounted UUID mismatch")
    if expected["fsType"] != "btrfs":
        require(
            os.makedev(major, minor) == dev.st_rdev == root.device,
            "mounted device number mismatch",
        )
    if expected.get("uuid"):
        found = subprocess.check_output(
            ["blkid", "-p", "-s", "UUID", "-o", "value", expected["device"]], text=True
        ).strip()
        require(found == expected["uuid"], "filesystem UUID mismatch")


def tag_escape(path: str) -> str:
    return (
        path.replace("\\", "\\\\")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace(":", "\\d")
    )


class Drain:
    def __init__(self, config: dict):
        self.config = config
        self.roots: dict[str, Root] = {}
        try:
            for disk in config["mounts"]:
                root = Root(disk["path"])
                self.roots[disk["id"]] = root
                admit(root, disk)
            if "cache" in self.roots:
                for disk in config["data"]:
                    distinct(self.roots["cache"], self.roots[disk])
                    require(
                        self.roots["cache"].device != self.roots[disk].device,
                        "cache and target share a filesystem",
                    )
        except BaseException:
            self.close()
            raise
        self.identity = hashlib.sha256(
            json.dumps(config, sort_keys=True).encode()
        ).hexdigest()

    def close(self) -> None:
        for root in self.roots.values():
            root.close()

    def admission(self) -> None:
        for disk in self.config["mounts"]:
            admit(self.roots[disk["id"]], disk)

    def candidates(self, limit: int) -> list[str]:
        root = self.roots["cache"]
        cutoff = time.time_ns() - self.config["ageMinutes"] * 60 * 1_000_000_000
        result = []
        # fwalk pins each visited directory; candidate opens later repeat nofollow
        # traversal. Excluded paths are reported, never silently called protected.
        for base, dirs, files, fd in os.fwalk(
            ".", dir_fd=root.fd, follow_symlinks=False
        ):
            require(mount_id(fd) == root.mount, "nested cache mount")
            dirs[:] = sorted(d for d in dirs if d != ".cache-mover-release")
            for name in sorted(files):
                path = name if base == "." else base[2:] + "/" + name
                info = os.stat(name, dir_fd=fd, follow_symlinks=False)
                if (
                    not stat.S_ISREG(info.st_mode)
                    or info.st_nlink != 1
                    or not protectable(path, self.config["excludes"])
                ):
                    print(
                        json.dumps(
                            {"retained": path, "reason": "excluded, hidden or linked"}
                        ),
                        file=sys.stderr,
                    )
                    continue
                if info.st_mtime_ns > cutoff:
                    continue
                result.append(path)
                if len(result) >= limit:
                    return result
        return result

    def state_root(self) -> Root:
        root = Root(self.config["stateDir"])
        info = os.fstat(root.fd)
        if info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o700:
            root.close()
            raise Unsafe("receipt directory must be private and owned by the caller")
        return root

    def save(self, name: str, value: dict) -> None:
        root = self.state_root()
        temporary = ".receipt-" + uuid.uuid4().hex
        try:
            fd = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                0o600,
                dir_fd=root.fd,
            )
            with os.fdopen(fd, "w") as stream:
                json.dump(value, stream, sort_keys=True)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(
                temporary, name + ".json", src_dir_fd=root.fd, dst_dir_fd=root.fd
            )
            os.fsync(root.fd)
        finally:
            root.close()

    def load(self, name: str) -> dict:
        root = self.state_root()
        try:
            with root.file(name + ".json") as fd:
                with os.fdopen(os.dup(fd)) as stream:
                    return json.load(stream)
        finally:
            root.close()

    def snapraid(self, *args: str, log: bool = False) -> subprocess.CompletedProcess:
        self.admission()
        # SnapRAID is path-based. Give it inherited pinned root descriptors,
        # not mountpoint strings that could resolve to placeholders after a
        # detach. The original declarative configuration remains the authority.
        with open(self.config["snapraidConfig"]) as stream:
            lines = stream.read().splitlines()
        for index, line in enumerate(lines):
            if line.split() and (
                line.split()[0] in ("data", "content", "parity")
                or line.split()[0].endswith("-parity")
            ):
                for root in self.roots.values():
                    line = line.replace(
                        " " + root.path + "/", f" /proc/self/fd/{root.fd}/"
                    )
                    if line.endswith(" " + root.path):
                        line = line[: -len(root.path)] + f"/proc/self/fd/{root.fd}"
                lines[index] = line
        config_fd = os.memfd_create("snapraid-pinned-config", os.MFD_CLOEXEC)
        with os.fdopen(config_fd, "w+") as pinned:
            pinned.write("\n".join(lines) + "\n")
            pinned.flush()
            return self.run_snapraid(config_fd, args, log)

    def run_snapraid(
        self, config_fd: int, args: tuple[str, ...], log: bool
    ) -> subprocess.CompletedProcess:
        command = [self.config["snapraid"], "-c", f"/proc/self/fd/{config_fd}"]
        log_path = self.config["stateDir"] + "/snapraid-" + uuid.uuid4().hex + ".log"
        if log:
            command += ["-l", log_path]
        result = subprocess.run(
            command + list(args),
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            env={**os.environ, "LC_ALL": "C"},
            pass_fds=(config_fd, *(root.fd for root in self.roots.values())),
        )
        print(result.stdout, file=sys.stderr)
        if log:
            require(result.returncode == 0, f"SnapRAID {args} failed")
            with open(log_path) as stream:
                result.stdout = stream.read()
            require(
                "summary:exit:ok\n" in result.stdout, "SnapRAID did not certify success"
            )
        return result

    def sync(self) -> None:
        result = self.snapraid("diff")
        removed, updated = diff_counts(result.returncode, result.stdout)
        require(
            removed <= self.config["maxRemoved"]
            and updated <= self.config["maxUpdated"],
            "SnapRAID diff threshold exceeded",
        )
        # Invalidate all protection receipts BEFORE any possible parity writes.
        self.save("generation", {"token": uuid.uuid4().hex})
        result = self.snapraid("sync")
        require(result.returncode == 0, "SnapRAID sync failed; no release authorized")

    def parity_evidence(self, hashes: bool = True) -> dict:
        with open(self.config["snapraidConfig"], "rb") as stream:
            config_hash = hashlib.sha256(stream.read()).hexdigest()
        result: dict = {
            "generation": self.load("generation"),
            "config": config_hash,
            "files": {},
        }
        for item in self.config["evidence"]:
            with self.roots[item["disk"]].file(item["path"]) as fd:
                info = snapshot(fd)
                if item["kind"] == "content" and hashes:
                    info["sha256"] = digest(fd)
                result["files"][item["disk"] + "/" + item["path"]] = info
        return result

    def copy(self, batch: str, limit: int, target: str | None) -> None:
        try:
            receipt = self.load(batch)
            require(
                receipt.get("version") == 1 and receipt["config"] == self.identity,
                "receipt version/configuration changed",
            )
        except FileNotFoundError:
            receipt = {
                "version": 1,
                "config": self.identity,
                "files": [],
                "pending": self.candidates(limit),
            }
            self.save(batch, receipt)
        while receipt["pending"]:
            path = receipt["pending"][0]
            self.admission()
            destinations = [
                disk for disk in self.config["data"] if target is None or disk == target
            ]
            require(bool(destinations), "target is not a configured data disk")
            # Refuse duplicate/conflicting names across ALL disks, not only the
            # selected branch. An existing single destination is adopted in place.
            existing = []
            for disk in self.config["data"]:
                try:
                    with self.roots[disk].parent(path) as (fd, name):
                        os.stat(name, dir_fd=fd, follow_symlinks=False)
                    existing.append(disk)
                except FileNotFoundError:
                    pass
            require(len(existing) <= 1, "destination appears on multiple disks")
            if existing:
                require(
                    target is None or target == existing[0],
                    "existing destination differs from requested target",
                )
                disk = existing[0]
            else:
                disk = max(
                    destinations,
                    key=lambda item: os.fstatvfs(self.roots[item].fd).f_bavail,
                )
            item = copy_file(self.roots["cache"], self.roots[disk], path)
            item["disk"] = disk
            receipt["files"].append(item)
            receipt["pending"].pop(0)
            receipt.pop("protection", None)
            self.save(batch, receipt)

    def verify_item(self, item: dict, source: bool = True) -> None:
        with self.roots[item["disk"]].file(item["path"]) as fd, lease(fd):
            require(
                snapshot(fd) == item["destination"]
                and metadata(fd) == item["metadata"]
                and digest(fd) == item["sha256"],
                "destination changed",
            )
        if source:
            with self.roots["cache"].file(item["path"]) as fd, lease(fd):
                require(
                    snapshot(fd) == item["source"]
                    and metadata(fd) == item["metadata"]
                    and digest(fd) == item["sha256"],
                    "source changed",
                )

    def protect(self, batch: str) -> None:
        receipt = self.load(batch)
        require(
            receipt.get("version") == 1
            and receipt["config"] == self.identity
            and not receipt["pending"],
            "batch incomplete/configuration changed",
        )
        require(
            all(item["state"] == "copied" for item in receipt["files"]),
            "batch already releasing; do not sync",
        )
        receipt.pop("protection", None)
        self.save(batch, receipt)
        for item in receipt["files"]:
            require(
                protectable(item["path"], self.config["excludes"]),
                "file excluded from protection",
            )
            self.verify_item(item)
        self.sync()
        listing = self.snapraid("list", log=True).stdout.splitlines()
        for item in receipt["files"]:
            disk_name = "d" + str(self.config["data"].index(item["disk"]) + 1)
            prefix = "file:" + disk_name + ":" + tag_escape(item["path"]) + ":"
            entries = [line for line in listing if line.startswith(prefix)]
            require(
                len(entries) == 1
                and int(entries[0][len(prefix) :].split(":")[0])
                == item["source"]["size"],
                "file absent from SnapRAID content",
            )
        before = self.parity_evidence()
        # Full check reads data AND parity. Audit-only is not sufficient.
        self.snapraid("check", log=True)
        for item in receipt["files"]:
            self.verify_item(item)
        require(before == self.parity_evidence(), "parity state changed during check")
        receipt["protection"] = before
        self.save(batch, receipt)

    def release(self, batch: str) -> None:
        receipt = self.load(batch)
        require(
            receipt.get("version") == 1
            and receipt["config"] == self.identity
            and not receipt["pending"],
            "batch incomplete/configuration changed",
        )
        require(
            receipt.get("protection") == self.parity_evidence(),
            "protection missing or invalidated; retain sources",
        )
        source = self.roots["cache"]
        # Private same-filesystem quarantine closes the pathname check/unlink
        # race. An interruption here retains bytes under the recorded path.
        created = False
        try:
            os.mkdir(".cache-mover-release", 0o700, dir_fd=source.fd)
            created = True
            os.fsync(source.fd)
        except FileExistsError:
            pass
        quarantine = os.open(".cache-mover-release", DIR, dir_fd=source.fd)
        try:
            if created:
                # Cache roots may be setgid; the private quarantine must not
                # inherit that mode or an access ACL from a media directory.
                os.fchmod(quarantine, 0o700)
                for key in os.listxattr(quarantine):
                    if key.startswith("system.posix_acl_"):
                        remove_xattr_if_present(quarantine, key)
                os.fsync(quarantine)
            info = os.fstat(quarantine)
            require(
                info.st_uid == os.geteuid()
                and stat.S_IMODE(info.st_mode) == 0o700
                and mount_id(quarantine) == source.mount,
                "unsafe quarantine directory",
            )
            for index, item in enumerate(receipt["files"]):
                if item["state"] == "released":
                    continue
                self.admission()
                self.verify_item(item, source=item["state"] == "copied")
                expected_evidence = {
                    **receipt["protection"],
                    "files": {
                        name: {
                            key: value for key, value in info.items() if key != "sha256"
                        }
                        for name, info in receipt["protection"]["files"].items()
                    },
                }
                require(
                    expected_evidence == self.parity_evidence(hashes=False),
                    "protection invalidated",
                )
                name = batch + "-" + str(index)
                # Keep both read leases until source unlink is durable.
                with self.roots[item["disk"]].file(item["path"]) as dest, lease(dest):
                    require(
                        snapshot(dest) == item["destination"]
                        and digest(dest) == item["sha256"],
                        "destination changed",
                    )
                    if item["state"] == "copied":
                        item["state"] = "releasing"
                        item["quarantine"] = ".cache-mover-release/" + name
                        self.save(batch, receipt)
                    try:
                        fd = os.open(name, READ, dir_fd=quarantine)
                    except FileNotFoundError:
                        # A crash after unlink but before the receipt update is
                        # ambiguous. Never infer release from a missing source.
                        with source.file(item["path"]) as original, lease(original):
                            require(
                                snapshot(original) == item["source"]
                                and digest(original) == item["sha256"],
                                "source changed before release",
                            )
                            with source.parent(item["path"]) as (parent, leaf):
                                rename_new(parent, leaf, quarantine, name)
                                os.fsync(parent)
                                os.fsync(quarantine)
                        fd = os.open(name, READ, dir_fd=quarantine)
                    try:
                        with lease(fd):
                            # rename changes ctime; every other source identity
                            # field and the full data/metadata must still agree.
                            actual = snapshot(fd)
                            expected = dict(item["source"])
                            actual.pop("ctime_ns")
                            expected.pop("ctime_ns")
                            require(
                                actual == expected
                                and metadata(fd) == item["metadata"]
                                and digest(fd) == item["sha256"],
                                "quarantined source changed; retained for operator recovery",
                            )
                            self.admission()
                            require(
                                snapshot(dest) == item["destination"]
                                and digest(dest) == item["sha256"],
                                "destination changed during release",
                            )
                            self.admission()
                            require(
                                expected_evidence == self.parity_evidence(hashes=False),
                                "protection invalidated before release",
                            )
                            os.unlink(name, dir_fd=quarantine)
                            os.fsync(quarantine)
                    finally:
                        os.close(fd)
                    item["state"] = "released"
                    self.save(batch, receipt)
        finally:
            os.close(quarantine)


def publish_status(
    config: dict, phase: str, receipt: dict | None = None, error: str | None = None
) -> None:
    """Public last-batch observation, deliberately not a live backlog estimate."""
    path = PurePosixPath(config["statusPath"])
    root = Root(str(path.parent))
    temporary = ".status-" + uuid.uuid4().hex
    try:
        info = os.fstat(root.fd)
        require(
            info.st_uid == os.geteuid() and not info.st_mode & 0o022,
            "unsafe status directory",
        )
        files = receipt["files"] if receipt is not None else None
        value = {
            "schemaVersion": 1,
            "observedAt": int(time.time()),
            "phase": phase,
            "pendingFiles": None,
            "pendingBytes": None,
            "protectedFiles": sum(item["state"] != "released" for item in files)
            if files is not None and receipt is not None and receipt.get("protection")
            else None,
            "releasedFiles": sum(item["state"] == "released" for item in files)
            if files is not None
            else None,
            "lastError": error,
        }
        fd = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
            0o644,
            dir_fd=root.fd,
        )
        with os.fdopen(fd, "w") as stream:
            os.fchmod(stream.fileno(), 0o644)
            json.dump(value, stream, sort_keys=True)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path.name, src_dir_fd=root.fd, dst_dir_fd=root.fd)
        os.fsync(root.fd)
    finally:
        root.close()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True)
    parser.add_argument(
        "command",
        choices=[
            "admit",
            "plan",
            "copy",
            "resume",
            "protect",
            "release",
            "sync",
            "scrub",
            "scheduled",
        ],
    )
    parser.add_argument("--batch")
    parser.add_argument("--target", help="configured direct data-disk ID")
    parser.add_argument("--limit", type=int, default=256)
    parser.add_argument(
        "--quiesced",
        action="store_true",
        help="required for operator release: writers and NFS consumers are paused",
    )
    args = parser.parse_args()
    require(args.limit > 0, "limit must be positive")
    if args.batch:
        require(
            re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,79}", args.batch) is not None
            and args.batch not in ("generation", "scheduled-current"),
            "unsafe/reserved batch name",
        )
    with open(args.config) as stream:
        config = json.load(stream)
    # All entry points (including admission) share the one lock inode. Never
    # unlink this lock, including during activation or failure recovery.
    lock = os.open(config["lock"], os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    locked = False
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        locked = True
        if args.command not in ("plan", "admit"):
            publish_status(config, args.command)
        drain = Drain(config)
        try:
            if args.command == "admit":
                return 0
            if args.command == "plan":
                print(
                    json.dumps(
                        {
                            "candidates": drain.candidates(args.limit),
                            "config": drain.identity,
                        }
                    )
                )
            elif args.command == "sync":
                drain.sync()
            elif args.command == "scrub":
                result = drain.snapraid("scrub", "-p", "8", "-o", "10")
                require(result.returncode == 0, "SnapRAID scrub failed")
            elif args.command == "scheduled":
                # Online scheduled work never releases. Explicit protect/release
                # follows coordinator quiescence; stale batches remain visible.
                try:
                    batch = drain.load("scheduled-current")["batch"]
                    previous = drain.load(batch)
                    finished = not previous["pending"] and all(
                        item["state"] == "released" for item in previous["files"]
                    )
                except FileNotFoundError:
                    finished = True
                if finished:
                    batch = "scheduled-" + uuid.uuid4().hex
                    drain.save("scheduled-current", {"batch": batch})
                drain.copy(batch, args.limit, args.target)
                args.batch = batch
                print(batch)
            else:
                require(args.batch is not None, "--batch required")
                if args.command in ("copy", "resume"):
                    drain.copy(args.batch, args.limit, args.target)
                elif args.command == "protect":
                    drain.protect(args.batch)
                else:
                    require(
                        args.quiesced,
                        "release requires --quiesced; pause writers and NFS consumers first",
                    )
                    drain.release(args.batch)
            if args.command not in ("plan", "admit"):
                publish_status(
                    config,
                    args.command + "-complete",
                    drain.load(args.batch) if args.batch else None,
                )
        finally:
            drain.close()
    except (Unsafe, OSError, ValueError, KeyError, subprocess.SubprocessError):
        if locked and args.command not in ("plan", "admit"):
            publish_status(config, "failed", error="operation-refused")
        raise
    finally:
        os.close(lock)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (Unsafe, OSError, ValueError, KeyError, subprocess.SubprocessError) as error:
        print(f"REFUSED: {error}", file=sys.stderr)
        sys.exit(1)
